/* Local thinking tools. No provider calls; capsules are scheduled reveals, not encrypted storage. */
(function(root){'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=v=>typeof v==='string'&&/^[-A-Za-z0-9_]{1,100}$/.test(v)&&!Object.hasOwn(Object.prototype,v),text=(v,max)=>typeof v==='string'&&v.length<=max;
function capsuleOffset(value,months){const d=new Date(value),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+months);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));return +d;}
function capsuleClosed(n,now=Date.now()){return !!(n.capsule?.sealed&&n.capsule.unlockAt>now);}
function capsuleStatus(n,now=Date.now()){return !n.capsule?.sealed?'Draft':capsuleClosed(n,now)?'Sealed until '+new Date(n.capsule.unlockAt).toLocaleString():'Ready to open';}
function calculator(){return {expression:'',box:'',history:[]};}
function calculate(c,solve,at=Date.now()){if(!c.expression.trim())throw Error('Enter a calculation first.');const expression=c.expression.trim(),result=solve(expression);c.history.unshift({expression,result,at});c.history=c.history.slice(0,30);return result;}
function calculatorHTML(c){return c.history.map(h=>'<p>'+esc(h.expression)+' = '+esc(h.result)+'</p>').join('')+(c.box?'<h2>Math box</h2><p>'+esc(c.box).replace(/\n/g,'<br>')+'</p>':'');}
function choice(uid){const options=['One possibility','Another possibility'].map(label=>({id:uid(),label,pros:'',cons:''}));return {view:'simple',options,criteria:[['Effort','lower'],['Cost','lower'],['Impact','higher'],['Personal fit','higher']].map(([label,prefer])=>({id:uid(),label,prefer,weight:'1'})),scores:{}};}
function choiceResults(c){const weights=c.criteria.map(r=>/^\d{1,2}$/.test(r.weight)&&Number(r.weight)<=10?Number(r.weight):NaN),total=weights.reduce((a,b)=>a+b,0),error=weights.some(w=>!Number.isFinite(w))?'Use whole-number weights from 0 to 10.':!total?'Give at least one criterion a positive weight.':'';if(error)return {error,rows:[]};
 const rows=c.options.map(o=>{let sum=0,missing=false;const working=c.criteria.map((r,i)=>{const raw=c.scores[o.id]?.[r.id]||'';if(!weights[i])return {label:r.label,weight:0,score:0,contribution:0,ignored:true};if(!/^[1-5]$/.test(raw)){missing=true;return {label:r.label,weight:weights[i],missing:true};}const rating=Number(raw),normalized=(r.prefer==='lower'?5-rating:rating-1)/4,contribution=100*normalized*weights[i]/total;sum+=contribution;return {label:r.label,weight:weights[i],rating,prefer:r.prefer,contribution};});return {id:o.id,label:o.label,score:missing?null:Number(sum.toFixed(2)),working};});
 const complete=rows.every(r=>r.score!==null),best=complete?Math.max(...rows.map(r=>r.score)):null;return {error:'',complete,rows,winners:complete?rows.filter(r=>r.score===best).map(r=>r.id):[]};}
function choiceHTML(c){const result=choiceResults(c);return c.options.map(o=>'<h2>'+esc(o.label||'Untitled option')+'</h2><h3>Pros</h3><p>'+esc(o.pros).replace(/\n/g,'<br>')+'</p><h3>Cons</h3><p>'+esc(o.cons).replace(/\n/g,'<br>')+'</p>').join('')+'<h2>Weighted comparison</h2>'+c.criteria.map(r=>'<p>'+esc(r.label)+' · weight '+esc(r.weight)+' · '+r.prefer+' is preferable</p>').join('')+result.rows.map(r=>'<h3>'+esc(r.label)+'</h3>'+r.working.map(w=>'<p>'+esc(w.label)+': '+(w.ignored?'not counted':w.missing?'rating needed':esc(w.rating)+' / 5 · contribution '+w.contribution.toFixed(2))+'</p>').join('')+'<p>'+(!result.complete?'Finish all active ratings before comparing totals.':'Score: '+r.score+' / 100')+'</p>').join('')+(result.error?'<p>'+esc(result.error)+'</p>':'');}
function reference(uid){const cardId=uid();return {view:'cards',fields:[{id:uid(),label:'Key detail'},{id:uid(),label:'Example'},{id:uid(),label:'Source'}],cards:[{id:cardId,title:'My first reference',tags:'',body:'',values:{},links:[]}],selected:cardId};}
function removeReferenceCard(r,cardId){r.cards=r.cards.filter(c=>c.id!==cardId);for(const card of r.cards)card.links=card.links.filter(id=>id!==cardId);if(r.selected===cardId)r.selected=r.cards[0]?.id||null;}
function referenceHTML(r){return r.cards.map(c=>'<h2>'+esc(c.title||'Untitled reference')+'</h2>'+(c.tags?'<p>Tags: '+esc(c.tags)+'</p>':'')+r.fields.map(f=>c.values[f.id]?'<h3>'+esc(f.label)+'</h3><p>'+esc(c.values[f.id]).replace(/\n/g,'<br>')+'</p>':'').join('')+(c.body?'<p>'+esc(c.body).replace(/\n/g,'<br>')+'</p>':'')+(c.links.length?'<p>Related: '+c.links.map(id=>esc(r.cards.find(c=>c.id===id)?.title||'Reference')).join(', ')+'</p>':'')).join('');}
function reminderRows(items,now=Date.now()){const rows=[];for(const n of items){if(n.deletedAt)continue;if(n.reminder)rows.push({kind:'note',item:n.id,title:n.title,body:capsuleClosed(n)?'Reminder for a sealed capsule':n.reminder.body,when:n.reminder.when,ongoing:false,done:!!n.reminder.fired,repeat:n.reminder.repeat});if(n.type==='task')for(const task of n.tasks||[])if(task.notification)rows.push({kind:'task',item:n.id,task:task.id,title:n.title,body:task.text,when:task.notification.when||0,ongoing:task.notification.ongoing,done:task.done});if(n.capsule?.sealed&&n.capsule.notify)rows.push({kind:'capsule',item:n.id,title:n.title,body:'Time Capsule reveal',when:n.capsule.unlockAt,ongoing:false,done:!!n.capsule.notifiedAt});}return rows.sort((a,b)=>(a.done-b.done)||((a.when||now)-(b.when||now)));}
function validateNote(n){if(n.capsule){const c=n.capsule;if(typeof c.sealed!=='boolean'||typeof c.notify!=='boolean'||c.rev!==undefined&&(!Number.isFinite(c.rev)||c.rev<=0||c.rev>1e15)||!Number.isFinite(c.unlockAt)||c.unlockAt<0||c.unlockAt>7258118399000||c.sealed&&!c.unlockAt||!Number.isFinite(c.createdAt)||c.createdAt<0||c.notifiedAt!==undefined&&(!Number.isFinite(c.notifiedAt)||c.notifiedAt<0))throw Error('Invalid time capsule');}
 if(n.calculator){const c=n.calculator;if(!text(c.expression,180)||!text(c.box,20000)||!Array.isArray(c.history)||c.history.length>30||c.history.some(h=>!h||!text(h.expression,180)||!Number.isFinite(h.result)||!Number.isFinite(h.at)||h.at<0))throw Error('Invalid calculator');}
 if(n.choice){const c=n.choice;if(!['simple','weighted'].includes(c.view)||!Array.isArray(c.options)||c.options.length<2||c.options.length>8||!Array.isArray(c.criteria)||!c.criteria.length||c.criteria.length>8||!c.scores||typeof c.scores!=='object'||Array.isArray(c.scores))throw Error('Invalid choice comparison');const options=new Set(),criteria=new Set();for(const o of c.options){if(!o||!id(o.id)||options.has(o.id)||!text(o.label,100)||!text(o.pros,4000)||!text(o.cons,4000))throw Error('Invalid choice option');options.add(o.id);}for(const r of c.criteria){if(!r||!id(r.id)||criteria.has(r.id)||!text(r.label,100)||!text(r.weight,2)||!['higher','lower'].includes(r.prefer))throw Error('Invalid choice criterion');criteria.add(r.id);}for(const [oid,values]of Object.entries(c.scores)){if(!options.has(oid)||!values||typeof values!=='object'||Array.isArray(values))throw Error('Invalid choice rating');for(const [cid,value]of Object.entries(values))if(!criteria.has(cid)||!text(value,2))throw Error('Invalid choice rating');}}
 if(n.reference){const r=n.reference;if(!['cards','table'].includes(r.view)||!Array.isArray(r.fields)||r.fields.length>8||!Array.isArray(r.cards)||r.cards.length>120)throw Error('Invalid reference lab');const fields=new Set(),cards=new Set();for(const f of r.fields){if(!f||!id(f.id)||fields.has(f.id)||!text(f.label,60))throw Error('Invalid reference field');fields.add(f.id);}for(const c of r.cards){if(!c||!id(c.id)||cards.has(c.id)||!text(c.title,160)||!text(c.tags,300)||!text(c.body,6000)||!c.values||typeof c.values!=='object'||Array.isArray(c.values)||Object.entries(c.values).some(([key,value])=>!fields.has(key)||!text(value,2000))||!Array.isArray(c.links)||c.links.length>8||c.links.some(v=>!id(v))||c.noteId!==undefined&&!id(c.noteId))throw Error('Invalid reference card');cards.add(c.id);}if(r.selected!==null&&!cards.has(r.selected)||r.cards.some(c=>c.links.some(v=>v===c.id||!cards.has(v))||new Set(c.links).size!==c.links.length))throw Error('Invalid reference link');}
 for(const mode of ['calculator','choice','reference'])if(n.inputMode===mode&&(n.type!=='note'||!n[mode]))throw Error('Missing thinking tool data');return n;}
const api={capsuleOffset,capsuleClosed,capsuleStatus,calculator,calculate,calculatorHTML,choice,choiceResults,choiceHTML,reference,removeReferenceCard,referenceHTML,reminderRows,validateNote};if(typeof module!=='undefined')module.exports=api;else root.NotaThinking=api;
})(typeof window!=='undefined'?window:globalThis);
